export type BannerSizeBucket =
  | 'rectangle'        // 300x250 / 250x250 / 336x280
  | 'horizontal-banner'// 468x60 / 728x90
  | 'skyscraper'       // 120x600 / 160x600
  | 'mobile-banner'    // 320x50
  | 'mini'             // 234x60 / 120x60 / 100x60 / 88x31 / 125x125
  | 'text-link';       // テキストリンクのみ

export interface BannerVariant {
  size: BannerSizeBucket;
  width?: number;
  height?: number;
  image?: string;       // /images/banners/<slug>-<w>x<h>.jpg
  a8url: string;
  anchorText?: string;  // text-link のみ
  html?: string;        // text-link の完全 HTML（オリジナル A8 スニペット）
}

export interface BannerProgram {
  id: string;           // ファイル名 slug
  programId: string;    // A8 program_id
  name: string;         // プログラム説明
  category: string;     // ジャンル（記事マッチング用）
  keywords: string[];   // タグ・キーワード（マッチングスコア用）
  variants: BannerVariant[]; // サイズ別バリエーション
}

// 後方互換: 旧 BannerEntry 形式（300x250 を primary として返す）
export interface BannerEntry {
  id: string;
  programId: string;
  name: string;
  category: string;
  keywords: string[];
  image: string;
  imageWidth: number;
  imageHeight: number;
  a8url: string;
}

